import * as OurStringification from "../src/stringification";
import * as OurTypes from "../src/types";

test("Result stringification round-trip Ok", () => {
  const literal = OurTypes.Result.Ok;

  const text = OurStringification.mustResultToString(literal);
  expect(text).toStrictEqual("ok");

  const nullableText = OurStringification.resultToString(literal);
  expect(nullableText).toStrictEqual("ok");

  const parsed = OurStringification.resultFromString(text);
  expect(parsed).toStrictEqual(literal);
});

test("Result stringification round-trip NotOk", () => {
  const literal = OurTypes.Result.NotOk;

  const text = OurStringification.mustResultToString(literal);
  expect(text).toStrictEqual("not-ok");

  const nullableText = OurStringification.resultToString(literal);
  expect(nullableText).toStrictEqual("not-ok");

  const parsed = OurStringification.resultFromString(text);
  expect(parsed).toStrictEqual(literal);
});

test("Result from invalid string", () => {
  const parsed = OurStringification.resultFromString(
    "invalid-literal"
  );

  expect(parsed).toBeNull();
});

test("Result invalid literal to string", () => {
  // The number 9007199254740991 is the maximum safe integer.
  const invalidLiteral = <OurTypes.Result>9007199254740991;

  expect(OurStringification.resultToString(invalidLiteral)).toBeNull();
  expect(() => OurStringification.mustResultToString(invalidLiteral)).toThrow();
});

